import { readFile } from 'node:fs/promises';

/** Settings read from a JSON file, with defaults for anything missing. */
export interface Settings {
  retries: number;
  timeoutMs: number;
}

const DEFAULTS: Settings = { retries: 3, timeoutMs: 5_000 };

/** Reads settings, rejecting values that are not positive integers. */
export async function readSettings(path: string): Promise<Settings> {
  const parsed: unknown = JSON.parse(await readFile(path, 'utf8'));
  if (typeof parsed !== 'object' || parsed === null) {
    throw new Error(`${path}: expected an object`);
  }
  const settings = { ...DEFAULTS, ...parsed } as Settings;
  for (const [key, value] of Object.entries(settings)) {
    if (!Number.isInteger(value) || value <= 0) {
      throw new Error(`${path}: ${key} must be a positive integer`);
    }
  }
  return settings;
}

