package store

import (
	"errors"
	"sync"
)

// ErrMissing is returned when a key has no value.
var ErrMissing = errors.New("store: missing key")

// Store is a map that is safe for concurrent use.
type Store struct {
	mu     sync.RWMutex
	values map[string]string
}

// Get returns the value for key, or ErrMissing.
func (s *Store) Get(key string) (string, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.values[key]
	if !ok {
		return "", ErrMissing
	}
	return v, nil
}

